import type { DeviceConfig, Op, OpResult, Snapshot } from './types';

export class ApiError extends Error {
  constructor(message: string, public code: string, public permanent = false) { super(message); }
}

export interface Api {
  ping(): Promise<{ ok: true; sheetName: string; tz: string; contributorId?: string; checks: Record<string, string> }>;
  snapshot(): Promise<Snapshot>;
  apply(ops: Op[]): Promise<OpResult[]>;
}

/**
 * Talks to the Apps Script web app. Bodies are sent as text/plain so the
 * browser makes a "simple" request (Apps Script can't answer a CORS
 * preflight); fetch follows Apps Script's redirect to googleusercontent.com.
 */
export function makeApi(cfg: DeviceConfig, timeoutMs = 45000, fetchFn: typeof fetch = (...a) => fetch(...a)): Api {
  async function post<T>(body: object): Promise<T> {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    let res: Response;
    try {
      res = await fetchFn(cfg.url, {
        method: 'POST', redirect: 'follow', signal: ctrl.signal,
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ key: cfg.key, ...body }),
      });
    } catch (e) {
      throw new ApiError(ctrl.signal.aborted ? 'The sheet took too long to answer.' : 'No connection to the sheet.', 'network');
    } finally {
      clearTimeout(timer);
    }
    if (!res.ok) throw new ApiError(`The sheet answered with HTTP ${res.status}.`, 'http');
    let data: any;
    try { data = await res.json(); } catch { throw new ApiError('The sheet sent an unexpected answer (is the web app deployed for "Anyone"?).', 'bad_response'); }
    if (!data || data.ok !== true) {
      const code = data?.code || 'error';
      throw new ApiError(data?.error || 'The sheet refused the request.', code, code === 'bad_key' || code === 'header_mismatch' || code === 'no_sheet');
    }
    return data as T;
  }
  return {
    ping: () => post({ op: 'ping' }),
    snapshot: () => post<Snapshot>({ op: 'snapshot' }),
    apply: async (ops) => (await post<{ ok: true; results: OpResult[] }>({ op: 'apply', ops })).results,
  };
}
