import { h, todayLocal, prettyDate, peso, timeAgo } from './dom';
import { kvGet, kvSet, kvDelete, requestPersistence } from './core/kv';
import { WriteQueue, type QueueStore, type QueuedOp } from './core/queue';
import { SyncEngine, type SyncStatus } from './core/sync';
import { makeApi, ApiError, type Api } from './core/api';
import { parseSetupCode } from './core/setupCode';
import { buildView, findByBarcode, findOpenLine, findLikelyDuplicate, priceHere, cheapest, normalizeBarcode, type View } from './core/model';
import { startSession, parsePrice, parsePackSize, planPriceSave, planNewItem, planLinkBarcode, type ScanSession, type ScanMode, type PriceInput } from './core/session';
import { standardUnitFor, unitChoices } from './core/units';
import type { DeviceConfig, Item, Snapshot, Op } from './core/types';
import { isContributorId } from './core/ids';
import { CameraScanner, cameraAvailable, cameraErrorMessage } from './scanner';
import { IdleHint, scanOutcome, type Point } from './core/scanFeedback';
import { describeScanner, type ScannerInfo } from './core/camera';
import { CameraOverlay, scanFeedback, unlockAudio } from './ui/scanFeedback';

/* ---------------- state ---------------- */

const idbQueueStore: QueueStore = {
  load: () => kvGet<QueuedOp[]>('queue'),
  save: (ops) => kvSet('queue', ops),
};

let config: DeviceConfig | null = null;
let api: Api | null = null;
let snapshot: Snapshot | null = null;
let session: ScanSession | null = null;
const queue = new WriteQueue(idbQueueStore);
const sync = new SyncEngine({
  queue,
  api: () => api,
  saveSnapshot: async (s) => {
    snapshot = s;
    await kvSet('snapshot', s);
    if (config && s.contributorId && isContributorId(s.contributorId) && config.contributorId !== s.contributorId) {
      config = { ...config, contributorId: s.contributorId };
      await kvSet('config', config);
    }
  },
});

type Screen = 'setup' | 'home' | 'scan' | 'item' | 'new';
let screen: Screen = 'home';
let root: HTMLElement;
let scanner: CameraScanner | null = null;
let videoEl: HTMLVideoElement | null = null;
let camOverlay: CameraOverlay | null = null;
/** Items only: "✓ … is already in Items", shown until the next scan or leaving the scanner. */
let alreadyMsg = '';
const READ_HINT = 'Can\'t read it yet — move closer, hold steady, or type the number below.';
const AIM_HINT = 'Point the camera at a barcode.';
let camMsgEl: HTMLElement | null = null;
const readHint = new IdleHint((show) => {
  if (camMsgEl && scanner?.running) camMsgEl.textContent = show ? READ_HINT : AIM_HINT;
});
/** How long the green outline shows before a camera scan opens its form. */
const OPEN_FORM_DELAY_MS = 300;
const finePointer = matchMedia('(pointer: fine)').matches;

function view(): View { return buildView(snapshot, queue.liveOps()); }
function storeName(id: string) { return view().stores.find((s) => s.id === id)?.name || id; }

/* ---------------- boot ---------------- */

export async function boot(el: HTMLElement) {
  root = el;
  await queue.init();
  config = (await kvGet<DeviceConfig>('config')) ?? null;
  snapshot = (await kvGet<Snapshot>('snapshot')) ?? null;
  const saved = await kvGet<ScanSession>('session');
  if (saved && (saved.mode === 'items' || saved.date === todayLocal())) session = saved;

  // A setup link opens the app with #setup=<code>. Read it once, then remove it from the address.
  if (location.hash.startsWith('#setup=')) {
    const raw = location.hash;
    history.replaceState(null, '', location.pathname + location.search);
    try { await applyConfig(parseSetupCode(raw)); }
    catch (e) { toast((e as Error).message, true); }
  }

  if (config) api = makeApi(config);
  requestPersistence();

  sync.onStatus(paintSyncChips);
  // Chrome allows sound only after a tap or key press; any one unlocks it.
  document.addEventListener('pointerdown', unlockAudio, true);
  document.addEventListener('keydown', unlockAudio, true);
  window.addEventListener('online', () => sync.syncNow());
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) { stopCamera(); readHint.stop(); }
    else { if (screen === 'scan') startCamera(); sync.tick(); }
  });
  window.addEventListener('popstate', onBack);
  setInterval(() => { if (navigator.onLine) sync.tick(); }, 15000);

  go(config ? 'home' : 'setup', false);
  if (config) sync.syncNow().then(() => { if (screen === 'home') render(); });
}

async function applyConfig(cfg: DeviceConfig) {
  const test = makeApi(cfg);
  toast('Checking the connection to your sheet…');
  try {
    const r = await test.ping();
    cfg.sheetName = r.sheetName || cfg.sheetName;
    if (r.contributorId && isContributorId(r.contributorId)) cfg.contributorId = r.contributorId;
  } catch (e) {
    if (e instanceof ApiError && e.permanent) throw new Error('The sheet refused this setup code: ' + e.message);
    // Offline or slow: keep the code anyway; sync will retry.
    toast('Saved. Could not reach the sheet right now (' + (e as Error).message + '). It will retry.', true);
  }
  config = cfg;
  api = makeApi(cfg);
  await kvSet('config', cfg);
  if (snapshot && snapshot.sheetName !== cfg.sheetName) { snapshot = null; await kvDelete('snapshot'); }
  await sync.syncNow();
  toast('Connected to ' + (cfg.sheetName || 'your sheet') + '.');
  go('home', false);
}

/* ---------------- navigation ---------------- */

let currentItem: Item | null = null;
let currentBarcode = '';

function go(next: Screen, push = true) {
  const deeper = (next === 'scan' && screen === 'home') || ((next === 'item' || next === 'new') && screen === 'scan');
  if (push && deeper) history.pushState({ screen: next }, '');
  if (next !== 'scan') { readHint.stop(); alreadyMsg = ''; }
  if (next !== 'scan' && next !== 'item' && next !== 'new') { stopCamera(); scanner = null; videoEl = null; camOverlay = null; }
  screen = next;
  render();
}

/** Phone back button / gesture. */
function onBack() {
  if (screen === 'item' || screen === 'new') backToScanner();
  else if (screen === 'scan') endSession();
}

function backToScanner() {
  screen = 'scan';
  render();
}

/* ---------------- rendering ---------------- */

function render() {
  root.replaceChildren();
  const s = screen;
  if (s === 'setup') root.append(setupScreen());
  else if (s === 'home') root.append(homeScreen());
  else if (s === 'scan') root.append(scanScreen());
  else if (s === 'item') root.append(itemScreen());
  else if (s === 'new') root.append(newItemScreen());
  paintSyncChips(sync.status);
  const auto = root.querySelector<HTMLElement>('[data-autofocus]');
  if (auto && (finePointer || auto.dataset.autofocus === 'always')) auto.focus();
}

function syncChip() {
  return h('button', { class: 'chip sync-chip', type: 'button', onclick: () => go('home') });
}

function paintSyncChips(st: SyncStatus) {
  const label =
    st.state === 'syncing' ? 'Syncing…' :
    st.failed ? `${st.failed} need attention` :
    st.pending ? `${st.pending} waiting to sync` :
    st.state === 'offline' ? 'Offline' :
    st.state === 'error' ? 'Sync problem' : 'All saved';
  const cls = st.failed || st.state === 'error' ? 'bad' : st.pending || st.state === 'offline' ? 'warn' : 'ok';
  root.querySelectorAll<HTMLElement>('.sync-chip').forEach((c) => { c.textContent = label; c.dataset.state = cls; });
  const detail = root.querySelector<HTMLElement>('#sync-detail');
  if (detail) detail.textContent = `Last sync: ${timeAgo(st.lastSyncAt)}${st.lastError ? ' · ' + st.lastError : ''}`;
  const failedBox = root.querySelector<HTMLElement>('#failed-box');
  if (failedBox) failedBox.replaceChildren(failedList());
}

let toastTimer = 0;
export function toast(msg: string, bad = false) {
  let t = document.getElementById('toast');
  if (!t) { t = h('div', { id: 'toast', role: 'status', 'aria-live': 'polite' }); document.body.append(t); }
  t.textContent = msg;
  t.className = 'show' + (bad ? ' bad' : '');
  clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => { t!.className = ''; }, bad ? 6000 : 2500);
}

/* ---------- setup ---------- */

function setupScreen() {
  const box = h('textarea', { rows: 4, placeholder: 'Paste the setup link or code here', 'aria-label': 'Setup link or code', autocapitalize: 'off', spellcheck: 'false' });
  const save = async () => {
    try { await applyConfig(parseSetupCode(box.value)); }
    catch (e) { toast((e as Error).message, true); }
  };
  return h('main', { class: 'screen' },
    h('h1', {}, 'Set up Grocer'),
    h('p', {}, 'Grocer saves to your own Google Sheet. Open the setup link from your sheet\'s Apps Script (run ', h('code', {}, 'setupLink'), ') on this device, or paste the link or code here.'),
    box,
    h('button', { class: 'big primary', type: 'button', onclick: save }, 'Use this code'),
    h('p', { class: 'muted' }, 'iPhone: if you added Grocer to your Home Screen, paste the code here; the Home Screen app does not share Safari\'s storage.'),
  );
}

/* ---------- home ---------- */

function homeScreen() {
  const v = view();
  let mode: ScanMode = session?.mode ?? 'store';
  const storeSel = h('select', { 'aria-label': 'Store' },
    h('option', { value: '' }, 'Choose a store…'),
    v.stores.map((s) => h('option', { value: s.id }, s.name)));
  const dateIn = h('input', { type: 'date', value: todayLocal(), 'aria-label': 'Date' });
  kvGet<string>('lastStoreId').then((id) => { if (id && !storeSel.value) storeSel.value = id; });
  if (session?.storeId) storeSel.value = session.storeId;

  const storeFields = h('div', { class: 'store-fields' },
    h('label', {}, 'Store', storeSel),
    h('label', {}, 'Date', dateIn));
  const modeBtns = (['store', 'items'] as ScanMode[]).map((m) =>
    h('button', { type: 'button', class: 'seg', 'aria-pressed': String(m === mode), onclick: () => setMode(m) },
      m === 'store' ? 'Prices at a store' : 'Items only'));
  const hint = h('p', { class: 'muted' });
  function setMode(m: ScanMode) {
    mode = m;
    modeBtns.forEach((b, i) => b.setAttribute('aria-pressed', String((i === 0 ? 'store' : 'items') === m)));
    storeFields.hidden = m !== 'store';
    hint.textContent = m === 'store'
      ? 'Scan items at one store on one date and type the shelf price. Leave a price blank to skip it.'
      : 'Scan to check or add products to Items. No prices are saved.';
  }
  setMode(mode);

  const start = async () => {
    if (mode === 'store' && !storeSel.value) { toast('Choose a store first.', true); storeSel.focus(); return; }
    if (mode === 'store' && !dateIn.value) { toast('Choose a date.', true); return; }
    const same = session && session.mode === mode && session.storeId === (mode === 'store' ? storeSel.value : '') && session.date === (mode === 'store' ? dateIn.value : '');
    if (!same) session = startSession(mode, storeSel.value, dateIn.value);
    unlockAudio();
    await kvSet('session', session);
    if (mode === 'store') await kvSet('lastStoreId', storeSel.value);
    go('scan');
  };

  return h('main', { class: 'screen' },
    h('header', { class: 'bar' }, h('h1', {}, 'Grocer'), syncChip()),
    !snapshot && h('p', { class: 'notice' }, 'Loading your stores and items from the sheet… You can still start; new barcodes will open the new-item form.'),
    h('section', { class: 'card' },
      h('div', { class: 'segs', role: 'group', 'aria-label': 'What are you scanning?' }, modeBtns),
      hint,
      storeFields,
      h('button', { class: 'big primary', type: 'button', onclick: start }, session ? 'Continue scanning' : 'Start scanning')),
    h('section', { class: 'card' },
      h('h2', {}, 'Sync'),
      h('p', { id: 'sync-detail', class: 'muted' }),
      h('button', { class: 'big', type: 'button', onclick: async () => { await sync.syncNow(); if (screen === 'home') render(); } }, 'Sync now'),
      h('div', { id: 'failed-box' })),
    h('details', { class: 'card' },
      h('summary', {}, 'This device'),
      h('p', {}, 'Sheet: ', h('strong', {}, config?.sheetName || '—')),
      h('p', { class: 'muted' }, 'Anonymous contributor ID: ', h('code', {}, config?.contributorId ? config.contributorId.slice(0, 9) + '…' : 'not yet (updates on next sync)')),
      h('p', { class: 'muted' }, `${v.items.length} items · ${v.stores.length} stores cached on this device.`),
      scannerInfoLine(),
      h('button', { class: 'big danger', type: 'button', onclick: forgetSetup }, 'Disconnect this device')),
  );
}

function failedList() {
  const f = queue.failed();
  if (!f.length) return h('div', {});
  return h('div', { class: 'failed' },
    h('h3', {}, 'The sheet refused these saves'),
    f.map((q) => h('div', { class: 'failed-row' },
      h('div', {}, h('strong', {}, describeOp(q.op)), h('div', { class: 'muted' }, q.error || '')),
      h('button', { type: 'button', onclick: () => queue.discard(q.op.opId) }, 'Discard'))),
    h('button', { class: 'big', type: 'button', onclick: async () => { await queue.retryFailed(); sync.syncNow(); } }, 'Try these again'));
}

function describeOp(op: Op): string {
  const v = view();
  if (op.type === 'item.upsert') return 'Item: ' + (op.item.name || v.itemById.get(op.item.id)?.name || op.item.id);
  if (op.type === 'price.upsert') return `Price: ${v.itemById.get(op.line.itemId)?.name || op.line.itemId} ${peso(op.line.price)} at ${storeName(op.line.storeId)}`;
  return 'Remove price line ' + op.id;
}

async function forgetSetup() {
  if (queue.pendingCount() && !confirm(`${queue.pendingCount()} saves have not reached the sheet yet and will be lost. Disconnect anyway?`)) return;
  if (!confirm('Disconnect this device from the sheet? You will need the setup code again.')) return;
  for (const k of ['config', 'snapshot', 'session', 'queue', 'lastStoreId']) await kvDelete(k);
  location.reload();
}

async function endSession() {
  stopCamera(); scanner = null;
  readHint.stop(); alreadyMsg = '';
  if (session?.mode === 'items') { session = null; await kvDelete('session'); }
  screen = 'home';
  render();
  sync.syncNow();
}

/* ---------- scanner ---------- */

function scanScreen() {
  const s = session!;
  const title = s.mode === 'store' ? `${storeName(s.storeId)} · ${prettyDate(s.date)}` : 'Items only';
  const input = h('input', {
    class: 'code-input', inputmode: 'numeric', autocomplete: 'off', enterkeyhint: 'go',
    placeholder: 'Type or use a USB scanner, then Enter', 'aria-label': 'Barcode', 'data-autofocus': '',
  });
  const lookUp = () => { unlockAudio(); const c = input.value; input.value = ''; onScan(c); };
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); lookUp(); }
  });
  const camMsg = h('p', { class: 'cam-msg muted', 'aria-live': 'polite' });
  camMsgEl = camMsg;
  videoEl ??= h('video', { class: 'video', playsinline: true, muted: true, 'aria-label': 'Camera view' });
  camOverlay ??= new CameraOverlay(videoEl);
  const camBtn = h('button', { class: 'big', type: 'button', onclick: () => { unlockAudio(); startCamera(camMsg); } }, 'Start camera');
  const torchBtn = h('button', { class: 'chip torch', type: 'button', hidden: true, 'aria-pressed': 'false', onclick: toggleTorch }, '🔦 Flashlight');

  const el = h('main', { class: 'screen scan' },
    h('header', { class: 'bar' },
      h('div', {}, h('div', { class: 'eyebrow' }, s.mode === 'store' ? 'Prices at a store' : 'Scanning'), h('h1', { class: 'small' }, title)),
      syncChip()),
    cameraAvailable() ? camOverlay.el : null,
    h('p', { id: 'already', class: 'already', role: 'status', hidden: !alreadyMsg }, alreadyMsg),
    h('div', { class: 'cam-tools' }, camMsg, torchBtn),
    cameraAvailable() && !scanner?.running ? camBtn : null,
    h('form', { class: 'code-form', onsubmit: (e: Event) => { e.preventDefault(); lookUp(); } },
      input, h('button', { class: 'go', type: 'submit' }, 'Look up')),
    h('div', { id: 'recent-box' }, recentList()),
    h('button', { class: 'big primary done', type: 'button', onclick: () => history.state?.screen ? history.back() : endSession() }, 'Done'),
  );
  if (cameraAvailable()) queueMicrotask(() => startCamera(camMsg, camBtn));
  return el;
}

function paintTorch() {
  const b = root.querySelector<HTMLButtonElement>('.torch');
  if (!b) return;
  b.hidden = !scanner?.torchSupported;
  b.setAttribute('aria-pressed', String(!!scanner?.torchOn));
  b.textContent = scanner?.torchOn ? '🔦 Flashlight on' : '🔦 Flashlight';
}

async function toggleTorch() {
  if (!scanner) return;
  await scanner.setTorch(!scanner.torchOn);
  paintTorch();
}

/** Saves what the scanner used (engine, camera size, focus, speed) for "This device", then releases the camera. */
function stopCamera() {
  saveScannerInfo();
  scanner?.stop();
}

function saveScannerInfo() {
  const info = scanner?.info();
  if (info) kvSet('scannerInfo', info);
}

function scannerInfoLine() {
  const p = h('p', { class: 'muted scanner-info' }, describeScanner(null));
  kvGet<ScannerInfo>('scannerInfo').then((i) => { p.textContent = describeScanner(i); });
  return p;
}

function recentList() {
  const recent = session!.recent.slice(0, 8);
  return recent.length ? h('section', {},
    h('h2', {}, 'This session'),
    h('ul', { class: 'recent' }, recent.map((r) => h('li', {},
      h('button', { type: 'button', onclick: () => onScan(r.barcode || '', r.itemId) }, r.label))))) : null;
}

/** Items only: show (or clear, with '') the "already in Items" banner and refresh "This session" without re-rendering the camera. */
function paintScanStatus(msg: string) {
  alreadyMsg = msg;
  const banner = root.querySelector<HTMLElement>('#already');
  if (banner) { banner.textContent = msg; banner.hidden = !msg; }
  root.querySelector('#recent-box')?.replaceChildren(recentList() ?? '');
}

async function startCamera(msgEl?: HTMLElement, btn?: HTMLElement) {
  if (!videoEl) return;
  if (!scanner) scanner = new CameraScanner(videoEl, {
    onCode: (code, corners) => onScan(code, undefined, corners, true),
    onRead: () => readHint.read(),
  });
  try {
    await scanner.start();
    btn?.remove();
    paintTorch();
    saveScannerInfo();
    if (msgEl) msgEl.textContent = AIM_HINT;
    if (screen === 'scan') readHint.start();
  } catch (e) {
    scanner.stop(); scanner = null;
    if (msgEl) msgEl.textContent = cameraErrorMessage(e);
  }
}

/**
 * A barcode from the camera, typing / USB scanner, or a tap on "This session" (itemId).
 * Reads give a beep + buzz; camera reads also outline the barcode:
 * green = a form opens, red = Items only and it is already in Items.
 */
function onScan(raw: string, itemId?: string, corners: Point[] | null = null, fromCamera = false) {
  if (screen !== 'scan') return;
  const code = normalizeBarcode(raw);
  const v = view();
  const item = itemId ? v.itemById.get(itemId) : code ? findByBarcode(v, code) : undefined;
  if (!item && !code) return;
  const outcome = scanOutcome(session!.mode, !!item);
  if (!itemId) scanFeedback(outcome, fromCamera ? camOverlay : null, corners);
  currentBarcode = code;
  currentItem = item ?? null;
  if (outcome === 'already') {
    remember(code, item!);
    paintScanStatus(`✓ ${item!.name} is already in Items`);
    return;
  }
  paintScanStatus('');
  scanner?.pause();
  readHint.stop();
  const open = () => { if (screen === 'scan') go(item ? 'item' : 'new'); };
  // Let the green outline show for a moment before the form covers the camera.
  if (fromCamera) window.setTimeout(open, OPEN_FORM_DELAY_MS); else open();
}

function remember(barcode: string, item: Item, extra = '') {
  const s = session!;
  s.recent = [{ barcode, itemId: item.id, label: item.name + extra, at: Date.now() }, ...s.recent.filter((r) => r.itemId !== item.id)].slice(0, 30);
  kvSet('session', s);
}

async function commit(ops: Op[], message: string, lineId?: string, existed?: boolean) {
  for (const op of ops) await queue.enqueue(op);
  if (lineId && !existed && ops.some((o) => o.type === 'price.upsert')) session!.createdLineIds.push(lineId);
  await kvSet('session', session);
  toast(message);
  sync.syncNow();
  if (history.state?.screen === 'item' || history.state?.screen === 'new') history.back();
  else backToScanner();
}

/* ---------- known item, price card (store mode) ---------- */

function priceFields(item: Item | null, existingPrice: number | '', packSize: number | '', packUnit: string, promo: boolean, units: string[]) {
  const price = h('input', { class: 'price', inputmode: 'decimal', autocomplete: 'off', placeholder: '0.00', value: existingPrice === '' ? '' : String(existingPrice), 'aria-label': 'Price', 'data-autofocus': 'always', enterkeyhint: 'done' });
  const pack = h('input', { inputmode: 'decimal', autocomplete: 'off', value: packSize === '' ? '' : String(packSize), 'aria-label': 'Pack size' });
  const unitSel = h('select', { 'aria-label': 'Pack unit' }, h('option', { value: '' }, '—'), units.map((u) => h('option', { value: u }, u)));
  unitSel.value = packUnit || item?.unit || '';
  const promoBox = h('input', { type: 'checkbox', checked: promo });
  const el = h('div', { class: 'price-fields' },
    h('label', { class: 'price-label' }, 'Shelf price (₱)', price),
    h('div', { class: 'row2' }, h('label', {}, 'Pack size', pack), h('label', {}, 'Unit', unitSel)),
    h('label', { class: 'check' }, promoBox, ' On promo / sale'));
  const read = (): PriceInput | string => {
    const p = parsePrice(price.value);
    if (p === null) return 'Price must be a number with up to 2 decimals.';
    const ps = parsePackSize(pack.value);
    if (ps === null) return 'Pack size must be a number.';
    return { price: p, packSize: ps, packUnit: unitSel.value, promo: promoBox.checked };
  };
  return { el, price, read };
}

function itemScreen() {
  const s = session!;
  const v = view();
  const item = currentItem!;
  const existing = findOpenLine(v, item.id, s.storeId, s.date);
  const here = priceHere(v, item.id, s.storeId);
  const best = cheapest(v, item.id);
  const units = unitChoices(v.units, v.items.map((i) => i.unit));
  const f = priceFields(item, existing?.price ?? '', existing?.packSize ?? item.lastPackSize ?? '', existing?.packUnit || item.unit, existing?.promo ?? false, units);
  const save = () => {
    const input = f.read();
    if (typeof input === 'string') { toast(input, true); return; }
    const plan = planPriceSave(view(), s, item, currentBarcode, input);
    remember(currentBarcode, item, input.price === '' ? '' : ' · ' + peso(input.price));
    commit(plan.ops, plan.message, plan.lineId, !!existing);
  };
  f.price.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); save(); } });
  return h('main', { class: 'screen form' },
    h('header', { class: 'bar' }, h('div', { class: 'eyebrow' }, storeName(s.storeId) + ' · ' + prettyDate(s.date)), syncChip()),
    h('h1', {}, item.name),
    h('p', { class: 'muted' }, [item.brand, item.category, item.unit].filter(Boolean).join(' · ')),
    h('dl', { class: 'facts' },
      existing && h('div', {}, h('dt', {}, 'Already saved today'), h('dd', {}, peso(existing.price))),
      here && h('div', {}, h('dt', {}, 'Last here'), h('dd', {}, `${peso(here.price)} · ${prettyDate(here.date)}`)),
      best && best.storeId !== s.storeId && h('div', {}, h('dt', {}, 'Cheapest'), h('dd', {}, `${peso(best.price)} at ${storeName(best.storeId)}`))),
    f.el,
    h('div', { class: 'actions' },
      h('button', { class: 'big', type: 'button', onclick: () => history.back() }, 'Skip'),
      h('button', { class: 'big primary', type: 'button', onclick: save }, 'Save')),
  );
}

/* ---------- unknown barcode, new item ---------- */

function newItemScreen() {
  const s = session!;
  const v = view();
  const store = v.stores.find((x) => x.id === s.storeId);
  const units = unitChoices(v.units, v.items.map((i) => i.unit));
  const name = h('input', { autocomplete: 'off', autocapitalize: 'words', 'aria-label': 'Name', 'data-autofocus': 'always', placeholder: 'e.g. Queen Baking Soda 1kg' });
  const brand = h('input', { autocomplete: 'off', autocapitalize: 'words', 'aria-label': 'Brand' });
  const cat = h('select', { 'aria-label': 'Category' }, h('option', { value: '' }, '—'), v.categories.map((c) => h('option', { value: c }, c)));
  cat.value = store?.defaultCategory || '';
  const unit = h('select', { 'aria-label': 'Unit' }, h('option', { value: '' }, 'Choose…'), units.map((u) => h('option', { value: u }, u)));
  const std = h('select', { 'aria-label': 'Standard unit' }, ['kg', 'L', 'pc'].map((u) => h('option', { value: u }, u)));
  unit.addEventListener('change', () => { std.value = standardUnitFor(unit.value); });
  const pf = s.mode === 'store' ? priceFields(null, '', '', '', false, units) : null;
  const warn = h('div', { class: 'dup', hidden: true });

  const fields = () => ({ barcode: currentBarcode, name: name.value.trim(), brand: brand.value.trim(), category: cat.value, unit: unit.value, standardUnit: std.value || standardUnitFor(unit.value) });
  const readInput = (): PriceInput | null | false => {
    if (!pf) return null;
    const r = pf.read();
    if (typeof r === 'string') { toast(r, true); return false; }
    return r;
  };
  const saveNew = () => {
    const input = readInput(); if (input === false) return;
    const plan = planNewItem(view(), s, fields(), input);
    const fake = { ...fields(), id: plan.itemId } as Item;
    remember(currentBarcode, fake);
    commit(plan.ops, plan.message, plan.lineId, false);
  };
  const linkTo = (dup: Item) => {
    const input = readInput(); if (input === false) return;
    const ops: Op[] = [planLinkBarcode(dup, currentBarcode)];
    let msg = `Barcode linked to ${dup.name}.`;
    let lineId: string | undefined; let existed = false;
    if (input && input.price !== '') {
      const v2 = buildView(snapshot, [...queue.liveOps(), ...ops]);
      existed = !!findOpenLine(v2, dup.id, s.storeId, s.date);
      const plan = planPriceSave(v2, s, dup, currentBarcode, input);
      ops.push(...plan.ops); lineId = plan.lineId; msg += ' ' + plan.message;
    }
    remember(currentBarcode, dup);
    commit(ops, msg, lineId, existed);
  };
  const save = () => {
    const f = fields();
    if (!f.name) { toast('Type a name.', true); name.focus(); return; }
    if (!f.unit) { toast('Choose a unit.', true); unit.focus(); return; }
    const dup = warn.hidden ? findLikelyDuplicate(view(), f.name, f.brand) : undefined;
    if (dup) {
      warn.hidden = false;
      warn.replaceChildren(
        h('p', {}, h('strong', {}, 'Looks like this is already in Items: '), `${dup.name}${dup.brand ? ' (' + dup.brand + ')' : ''}`,
          dup.barcode ? ` — it already has barcode ${dup.barcode}.` : ' — it has no barcode yet.'),
        ...(dup.barcode ? [] : [h('button', { class: 'big primary', type: 'button', onclick: () => linkTo(dup) }, 'Same item: link this barcode')]),
        h('button', { class: 'big', type: 'button', onclick: saveNew }, 'Different item: add it'));
      warn.scrollIntoView({ block: 'center' });
      return;
    }
    saveNew();
  };

  pf?.price.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); save(); } });
  return h('main', { class: 'screen form' },
    h('header', { class: 'bar' }, h('div', { class: 'eyebrow' }, 'New item' + (s.mode === 'store' ? ' · ' + storeName(s.storeId) : '')), syncChip()),
    h('h1', {}, currentBarcode ? 'Barcode ' + currentBarcode : 'New item'),
    h('p', { class: 'muted' }, 'This barcode is not in Items yet.'),
    h('label', {}, 'Name', name),
    h('label', {}, 'Brand', brand),
    h('div', { class: 'row2' }, h('label', {}, 'Category', cat), h('label', {}, 'Unit', unit)),
    h('label', {}, 'Standard unit (for price per kg / L / pc)', std),
    pf?.el,
    warn,
    h('div', { class: 'actions' },
      h('button', { class: 'big', type: 'button', onclick: () => history.back() }, 'Cancel'),
      h('button', { class: 'big primary', type: 'button', onclick: save }, 'Save')),
  );
}
