/**
 * What the user sees, hears and feels when a barcode is read:
 * a beep (WebAudio), a vibration, and a coloured outline around the barcode
 * on the camera view plus a flash of the camera frame's border.
 *   green ('go')      = read OK, a form opens
 *   red   ('already') = Items only: already in Items, stay on the camera
 */
import { h } from '../dom';
import { mapToDisplay, polygonAttr, type Point, type ScanOutcome } from '../core/scanFeedback';

const OUTLINE_MS = 800;
const FLASH_MS = 600;
const SVG_NS = 'http://www.w3.org/2000/svg';

/* ---------- sound ---------- */

let audio: AudioContext | null = null;

/**
 * Create / resume the one AudioContext. Chrome only lets a page make sound
 * after a tap, so this runs on taps (Start scanning, Start camera, Look up,
 * and any tap on the page). Plays at media volume.
 */
export function unlockAudio() {
  try {
    const Ctx = window.AudioContext || (window as any).webkitAudioContext;
    if (!Ctx) return;
    audio ??= new Ctx();
    if (audio.state === 'suspended') audio.resume().catch(() => {});
  } catch { /* no sound on this device; vibration and colours still work */ }
}

function tone(ctx: AudioContext, startAt: number, freq: number, ms: number, type: OscillatorType, peak: number) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  const end = startAt + ms / 1000;
  // Short ramps in and out so the beep doesn't click.
  gain.gain.setValueAtTime(0.0001, startAt);
  gain.gain.exponentialRampToValueAtTime(peak, startAt + 0.008);
  gain.gain.setValueAtTime(peak, end - 0.02);
  gain.gain.exponentialRampToValueAtTime(0.0001, end);
  osc.connect(gain).connect(ctx.destination);
  osc.start(startAt);
  osc.stop(end + 0.01);
}

function beep(outcome: ScanOutcome) {
  if (!audio || audio.state !== 'running') return;
  const t = audio.currentTime + 0.01;
  if (outcome === 'go') tone(audio, t, 1800, 120, 'sine', 0.35);
  else { tone(audio, t, 660, 90, 'square', 0.12); tone(audio, t + 0.15, 660, 90, 'square', 0.12); }
}

/* ---------- vibration ---------- */

function buzz(outcome: ScanOutcome) {
  try { navigator.vibrate?.(outcome === 'go' ? 150 : [80, 60, 80]); } catch { /* unsupported */ }
}

/* ---------- camera overlay ---------- */

/**
 * The camera box: the video, the aim line and an SVG layer for outlines.
 * Built once per scan session and reused across re-renders, like the video.
 */
export class CameraOverlay {
  readonly el: HTMLDivElement;
  private svg: SVGSVGElement;
  private outlineTimer = 0;
  private flashTimer = 0;

  constructor(private video: HTMLVideoElement) {
    this.svg = document.createElementNS(SVG_NS, 'svg');
    this.svg.setAttribute('class', 'cam-overlay');
    this.svg.setAttribute('aria-hidden', 'true');
    this.el = h('div', { class: 'cam' }, video, h('div', { class: 'aim' }));
    this.el.append(this.svg);
  }

  /** Outline the barcode (corner points in video pixels) and flash the frame. */
  show(outcome: ScanOutcome, corners: Point[] | null) {
    const color = outcome === 'go' ? 'ok' : 'already';
    this.el.dataset.flash = color;
    clearTimeout(this.flashTimer);
    this.flashTimer = window.setTimeout(() => { delete this.el.dataset.flash; }, FLASH_MS);

    clearTimeout(this.outlineTimer);
    this.svg.replaceChildren();
    if (!corners) return;
    const box = { width: this.video.clientWidth, height: this.video.clientHeight };
    const fit = getComputedStyle(this.video).objectFit === 'contain' ? 'contain' : 'cover';
    const pts = mapToDisplay(corners, { width: this.video.videoWidth, height: this.video.videoHeight }, box, fit);
    if (!pts.length) return;
    this.svg.setAttribute('viewBox', `0 0 ${box.width} ${box.height}`);
    const poly = document.createElementNS(SVG_NS, 'polygon');
    poly.setAttribute('points', polygonAttr(pts));
    poly.setAttribute('class', 'outline ' + color);
    this.svg.append(poly);
    this.outlineTimer = window.setTimeout(() => this.svg.replaceChildren(), OUTLINE_MS);
  }
}

/** Beep + buzz, and the outline/flash when the read came from the camera box on screen. */
export function scanFeedback(outcome: ScanOutcome, overlay: CameraOverlay | null, corners: Point[] | null) {
  beep(outcome);
  buzz(outcome);
  if (overlay?.el.isConnected) overlay.show(outcome, corners);
}
