/** Standard unit for comparing prices, following the existing Items data (g→kg, mL→L, counts→pc). */
export function standardUnitFor(unit: string): string {
  const u = unit.trim();
  if (u === 'g' || u === 'kg') return 'kg';
  if (u === 'mL' || u === 'L') return 'L';
  return 'pc';
}

/** Units offered on the new-item form: the Units tab plus every unit already used in Items, A–Z. */
export function unitChoices(unitsTab: string[], itemUnits: string[]): string[] {
  const set = new Set<string>();
  [...unitsTab, ...itemUnits].forEach((u) => { const t = u.trim(); if (t) set.add(t); });
  return [...set].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}
