import type { Op, OpResult } from './types';

/**
 * On-device write queue. Every save becomes an Op here first (so the screen
 * never waits), then the sync engine sends batches to the data API.
 *
 * - Ops are kept in order and persisted after every change.
 * - An unsent op for the same item/line is replaced instead of piling up.
 * - Ops the server rejects are kept as "failed" with the reason, so nothing
 *   disappears silently; they can be discarded from the sync screen.
 */
export interface QueuedOp {
  op: Op;
  status: 'pending' | 'failed';
  attempts: number;
  queuedAt: number;
  error?: string;
}

export interface QueueStore {
  load(): Promise<QueuedOp[] | undefined>;
  save(ops: QueuedOp[]): Promise<void>;
}

export class MemoryQueueStore implements QueueStore {
  data: QueuedOp[] | undefined;
  async load() { return this.data ? structuredClone(this.data) : undefined; }
  async save(ops: QueuedOp[]) { this.data = structuredClone(ops); }
}

function entityKey(op: Op): string {
  if (op.type === 'item.upsert') return 'item:' + op.item.id;
  if (op.type === 'price.upsert') return 'price:' + op.line.id;
  return 'price:' + op.id;
}

export class WriteQueue {
  private ops: QueuedOp[] = [];
  private inFlight = new Set<string>();
  private listeners = new Set<() => void>();

  constructor(private store: QueueStore, private now: () => number = Date.now) {}

  async init() {
    this.ops = (await this.store.load()) ?? [];
    this.inFlight.clear();
  }

  onChange(fn: () => void) { this.listeners.add(fn); return () => this.listeners.delete(fn); }

  private async changed() {
    await this.store.save(this.ops);
    this.listeners.forEach((fn) => fn());
  }

  all(): readonly QueuedOp[] { return this.ops; }
  /** Ops still to be reflected in what the screen shows (pending + in flight; failed ones are not). */
  liveOps(): Op[] { return this.ops.filter((q) => q.status === 'pending').map((q) => q.op); }
  pendingCount() { return this.ops.filter((q) => q.status === 'pending').length; }
  failed() { return this.ops.filter((q) => q.status === 'failed'); }

  async enqueue(op: Op) {
    const key = entityKey(op);
    const idx = this.ops.findIndex((q) => q.status === 'pending' && !this.inFlight.has(q.op.opId) && entityKey(q.op) === key);
    if (idx >= 0) {
      const prev = this.ops[idx];
      if (op.type === 'item.upsert' && prev.op.type === 'item.upsert') {
        prev.op = { ...op, item: { ...prev.op.item, ...op.item } };
      } else if (op.type === 'price.delete' && prev.op.type === 'price.upsert') {
        // The line may already exist on the server from an earlier send, so still send the delete.
        this.ops.splice(idx, 1);
        this.ops.push({ op, status: 'pending', attempts: 0, queuedAt: this.now() });
      } else {
        prev.op = op;
      }
    } else {
      this.ops.push({ op, status: 'pending', attempts: 0, queuedAt: this.now() });
    }
    await this.changed();
  }

  /** Marks up to `max` pending ops as in flight and returns them in order. */
  takeBatch(max = 50): Op[] {
    const batch: Op[] = [];
    for (const q of this.ops) {
      if (batch.length >= max) break;
      if (q.status === 'pending' && !this.inFlight.has(q.op.opId)) {
        this.inFlight.add(q.op.opId);
        batch.push(q.op);
      }
    }
    return batch;
  }

  /** Server answered: drop the ops it accepted, keep rejected ones as failed. */
  async settle(results: OpResult[]) {
    const byId = new Map(results.map((r) => [r.opId, r]));
    const keep: QueuedOp[] = [];
    for (const q of this.ops) {
      const r = byId.get(q.op.opId);
      if (r && this.inFlight.has(q.op.opId)) {
        this.inFlight.delete(q.op.opId);
        if (r.ok) continue;
        keep.push({ ...q, status: 'failed', attempts: q.attempts + 1, error: r.error || r.code || 'Rejected' });
      } else {
        keep.push(q);
      }
    }
    // Anything sent but not mentioned in the answer goes back to pending.
    this.inFlight.clear();
    this.ops = keep;
    await this.changed();
  }

  /** Send failed (network, timeout, server busy): put the batch back, untouched, for a retry. */
  async retryLater(opIds: string[], error: string) {
    for (const q of this.ops) {
      if (opIds.includes(q.op.opId)) { q.attempts += 1; q.error = error; }
    }
    opIds.forEach((id) => this.inFlight.delete(id));
    await this.changed();
  }

  async discard(opId: string) {
    this.ops = this.ops.filter((q) => q.op.opId !== opId);
    await this.changed();
  }

  async retryFailed() {
    this.ops.forEach((q) => { if (q.status === 'failed') { q.status = 'pending'; q.error = undefined; } });
    await this.changed();
  }
}
