import { ApiError, type Api } from './api';
import type { Snapshot } from './types';
import type { WriteQueue } from './queue';

export interface SyncStatus {
  state: 'idle' | 'syncing' | 'offline' | 'error';
  pending: number;
  failed: number;
  lastSyncAt: number | null;
  lastError: string | null;
}

export interface SyncDeps {
  queue: WriteQueue;
  api: () => Api | null;
  saveSnapshot: (s: Snapshot) => Promise<void>;
  isOnline?: () => boolean;
  now?: () => number;
}

/**
 * Background sync: sends queued saves in batches and refreshes the cached
 * copy of the sheet. Runs on a timer while the app is open, when the device
 * comes back online, and on "Sync now". Network failures back off and retry;
 * nothing is lost because the queue is on the device.
 */
export class SyncEngine {
  status: SyncStatus = { state: 'idle', pending: 0, failed: 0, lastSyncAt: null, lastError: null };
  private running: Promise<void> | null = null;
  private nextTryAt = 0;
  private backoffMs = 0;
  private lastSnapshotAt = 0;
  private listeners = new Set<(s: SyncStatus) => void>();
  readonly snapshotMaxAgeMs = 5 * 60 * 1000;

  constructor(private d: SyncDeps) {
    d.queue.onChange(() => this.emit());
  }

  onStatus(fn: (s: SyncStatus) => void) { this.listeners.add(fn); return () => this.listeners.delete(fn); }

  private emit(patch: Partial<SyncStatus> = {}) {
    this.status = { ...this.status, ...patch, pending: this.d.queue.pendingCount(), failed: this.d.queue.failed().length };
    this.listeners.forEach((fn) => fn(this.status));
  }

  private now() { return (this.d.now ?? Date.now)(); }
  private online() { return (this.d.isOnline ?? (() => navigator.onLine))(); }

  /** Called by the timer: does work only when there is something to do and backoff allows. */
  tick(): Promise<void> {
    if (this.now() < this.nextTryAt) return Promise.resolve();
    const needSnapshot = this.now() - this.lastSnapshotAt > this.snapshotMaxAgeMs;
    if (this.d.queue.pendingCount() === 0 && !needSnapshot) return Promise.resolve();
    return this.run(needSnapshot);
  }

  /** "Sync now": ignores backoff, always refreshes the sheet copy. */
  syncNow(): Promise<void> {
    this.nextTryAt = 0;
    return this.run(true);
  }

  private run(refresh: boolean): Promise<void> {
    if (this.running) return this.running;
    this.running = this.doRun(refresh).finally(() => { this.running = null; });
    return this.running;
  }

  private async doRun(refresh: boolean) {
    const api = this.d.api();
    if (!api) return;
    if (!this.online()) { this.emit({ state: 'offline' }); return; }
    this.emit({ state: 'syncing' });
    let sent = false;
    try {
      for (let guard = 0; guard < 20; guard++) {
        const batch = this.d.queue.takeBatch(50);
        if (!batch.length) break;
        try {
          const results = await api.apply(batch);
          await this.d.queue.settle(results);
          sent = true;
        } catch (e) {
          await this.d.queue.retryLater(batch.map((o) => o.opId), (e as Error).message);
          throw e;
        }
      }
      if (refresh || sent) {
        const snap = await api.snapshot();
        await this.d.saveSnapshot(snap);
        this.lastSnapshotAt = this.now();
      }
      this.backoffMs = 0;
      this.nextTryAt = 0;
      this.emit({ state: 'idle', lastSyncAt: this.now(), lastError: null });
    } catch (e) {
      const err = e as ApiError;
      this.backoffMs = Math.min(60000, this.backoffMs ? this.backoffMs * 2 : 5000);
      this.nextTryAt = this.now() + this.backoffMs;
      this.emit({ state: err.code === 'network' && !this.online() ? 'offline' : 'error', lastError: err.message });
    }
  }
}
