/**
 * Pure helpers behind the scanner's feedback (no DOM, so they are unit-tested):
 * - where to draw the outline around a detected barcode on the camera view;
 * - which kind of feedback a scan gets;
 * - the "can't read it yet" hint timer.
 */

export interface Point { x: number; y: number }
export interface Rect { x: number; y: number; width: number; height: number }

/** What BarcodeDetector (native or the ZXing ponyfill) returns per barcode, as far as we use it. */
export interface DetectedBarcode {
  rawValue: string;
  cornerPoints?: readonly Point[];
  boundingBox?: Rect;
}

/**
 * The barcode's corners in video-frame pixels: cornerPoints when the detector
 * gives four of them, otherwise the bounding box's corners, otherwise null.
 */
export function cornersOf(b: DetectedBarcode): Point[] | null {
  const cp = b.cornerPoints;
  if (cp && cp.length >= 4 && cp.every((p) => Number.isFinite(p.x) && Number.isFinite(p.y))) {
    return cp.map((p) => ({ x: p.x, y: p.y }));
  }
  const r = b.boundingBox;
  if (r && r.width > 0 && r.height > 0) {
    return [
      { x: r.x, y: r.y }, { x: r.x + r.width, y: r.y },
      { x: r.x + r.width, y: r.y + r.height }, { x: r.x, y: r.y + r.height },
    ];
  }
  return null;
}

/**
 * Maps points from the video's own pixels (videoWidth × videoHeight) to the
 * displayed element's CSS pixels, for object-fit cover (cropped to fill) or
 * contain (letterboxed), centred (the default object-position).
 */
export function mapToDisplay(
  points: readonly Point[],
  video: { width: number; height: number },
  box: { width: number; height: number },
  fit: 'cover' | 'contain' = 'cover',
): Point[] {
  if (!video.width || !video.height || !box.width || !box.height) return [];
  const sx = box.width / video.width;
  const sy = box.height / video.height;
  const scale = fit === 'cover' ? Math.max(sx, sy) : Math.min(sx, sy);
  const dx = (box.width - video.width * scale) / 2;
  const dy = (box.height - video.height * scale) / 2;
  return points.map((p) => ({ x: p.x * scale + dx, y: p.y * scale + dy }));
}

/** SVG polygon `points` attribute, rounded to 0.1 px. */
export function polygonAttr(points: readonly Point[]): string {
  return points.map((p) => `${Math.round(p.x * 10) / 10},${Math.round(p.y * 10) / 10}`).join(' ');
}

/**
 * 'go'      = read OK, a form opens (green).
 * 'already' = Items-only mode and the item is already in Items; stay on the camera (red).
 */
export type ScanOutcome = 'go' | 'already';

export function scanOutcome(mode: 'items' | 'store', known: boolean): ScanOutcome {
  return mode === 'items' && known ? 'already' : 'go';
}

export interface Timers {
  set(fn: () => void, ms: number): unknown;
  clear(handle: unknown): void;
}

const realTimers: Timers = {
  set: (fn, ms) => setTimeout(fn, ms),
  clear: (h) => clearTimeout(h as ReturnType<typeof setTimeout>),
};

/**
 * Shows one hint when the camera has been running for `delayMs` without
 * reading any barcode. Any read hides it and restarts the wait; stop() hides
 * it and cancels the wait.
 */
export class IdleHint {
  private handle: unknown = null;
  private shown = false;

  constructor(private onChange: (show: boolean) => void, private delayMs = 5000, private timers: Timers = realTimers) {}

  get visible() { return this.shown; }

  /** Camera started (or resumed): wait from now. */
  start() { this.arm(); }

  /** A barcode was read (fresh or not): hide the hint and wait again. */
  read() { this.arm(); }

  stop() {
    this.cancel();
    this.set(false);
  }

  private arm() {
    this.cancel();
    this.set(false);
    this.handle = this.timers.set(() => { this.handle = null; this.set(true); }, this.delayMs);
  }

  private cancel() {
    if (this.handle !== null) this.timers.clear(this.handle);
    this.handle = null;
  }

  private set(show: boolean) {
    if (show === this.shown) return;
    this.shown = show;
    this.onChange(show);
  }
}
