import type { Item, LatestPrice, Op, PriceLine, Snapshot, Store } from './types';

/**
 * What the screens show: the last snapshot from the sheet with the unsent
 * saves laid on top, so a save is visible immediately (optimistic UI).
 */
export interface View {
  stores: Store[];
  items: Item[];
  itemById: Map<string, Item>;
  itemByBarcode: Map<string, Item>;
  categories: string[];
  units: string[];
  latest: LatestPrice[];
  openLines: PriceLine[];
}

export function emptyItem(id: string): Item {
  return { id, barcode: '', name: '', brand: '', category: '', unit: '', standardUnit: '', lastPrice: '', lastStoreId: '', lastPackSize: '', lastPromo: false, lastDate: '' };
}

export function buildView(snap: Snapshot | null, ops: readonly Op[]): View {
  const items = new Map<string, Item>();
  (snap?.items ?? []).forEach((it) => items.set(it.id, { ...it }));
  const lines = new Map<string, PriceLine>();
  (snap?.openLines ?? []).forEach((l) => lines.set(l.id, { ...l }));

  for (const op of ops) {
    if (op.type === 'item.upsert') {
      const cur = items.get(op.item.id) ?? emptyItem(op.item.id);
      const patch = Object.fromEntries(Object.entries(op.item).filter(([, v]) => v !== undefined));
      items.set(op.item.id, { ...cur, ...patch });
    } else if (op.type === 'price.upsert') {
      lines.set(op.line.id, { ...op.line });
      const it = items.get(op.line.itemId);
      if (it && (!it.lastDate || it.lastPrice === '' || it.lastDate <= op.line.date)) {
        items.set(it.id, { ...it, lastPrice: op.line.price, lastStoreId: op.line.storeId, lastPackSize: op.line.packSize, lastPromo: op.line.promo, lastDate: op.line.date });
      }
    } else if (op.type === 'price.delete') {
      lines.delete(op.id);
    }
  }

  const itemList = [...items.values()];
  const itemByBarcode = new Map<string, Item>();
  itemList.forEach((it) => { if (it.barcode) itemByBarcode.set(normalizeBarcode(it.barcode), it); });
  return {
    stores: [...(snap?.stores ?? [])].sort((a, b) => a.name.localeCompare(b.name)),
    items: itemList,
    itemById: items,
    itemByBarcode,
    categories: snap?.categories ?? [],
    units: snap?.units ?? [],
    latest: snap?.latest ?? [],
    openLines: [...lines.values()],
  };
}

/** Barcodes are compared as plain digit strings (the sheet may hold them as numbers or text). */
export function normalizeBarcode(raw: string): string {
  return String(raw).trim().replace(/^'/, '').replace(/\s+/g, '');
}

export function findByBarcode(view: View, raw: string): Item | undefined {
  const code = normalizeBarcode(raw);
  return view.itemByBarcode.get(code)
    // UPC-A (12 digits) is EAN-13 with a leading 0; scanners report either form.
    ?? (code.length === 12 ? view.itemByBarcode.get('0' + code) : undefined)
    ?? (code.length === 13 && code.startsWith('0') ? view.itemByBarcode.get(code.slice(1)) : undefined);
}

/** The unlinked line for this item at this store on this date, if any (rescan edits it). */
export function findOpenLine(view: View, itemId: string, storeId: string, date: string): PriceLine | undefined {
  return view.openLines.find((l) => l.itemId === itemId && l.storeId === storeId && l.date === date);
}

/** Same name + brand (ignoring case and spacing): likely the same product. */
export function findLikelyDuplicate(view: View, name: string, brand: string, exceptId?: string): Item | undefined {
  const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const n = norm(name), b = norm(brand);
  if (!n) return undefined;
  return view.items.find((it) => it.id !== exceptId && norm(it.name) === n && norm(it.brand) === b);
}

export function priceHere(view: View, itemId: string, storeId: string): LatestPrice | undefined {
  return view.latest.find((l) => l.itemId === itemId && l.storeId === storeId);
}

export function cheapest(view: View, itemId: string): LatestPrice | undefined {
  return view.latest.find((l) => l.itemId === itemId && l.cheapest);
}
