import type { DeviceConfig } from './types';

/** Decodes the code printed by setupLink (base64url JSON {v,u,k,n}). Throws a readable error. */
export function parseSetupCode(raw: string): DeviceConfig {
  const code = raw.trim().replace(/^.*#setup=/, '').replace(/\s+/g, '');
  let obj: { v?: number; u?: string; k?: string; n?: string };
  try {
    const b64 = code.replace(/-/g, '+').replace(/_/g, '/');
    const padded = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
    const bin = atob(padded);
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    obj = JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    throw new Error('That setup code could not be read. Copy it again from the Apps Script log.');
  }
  if (obj.v !== 1 || typeof obj.u !== 'string' || typeof obj.k !== 'string') throw new Error('That setup code is incomplete.');
  let url: URL;
  try { url = new URL(obj.u); } catch { throw new Error('The web app address in the setup code is not valid.'); }
  if (url.protocol !== 'https:' || !/(^|\.)script\.google\.com$/.test(url.hostname) || !/\/exec$/.test(url.pathname)) {
    throw new Error('The setup code must point at an Apps Script web app (https://script.google.com/…/exec).');
  }
  if (!/^[0-9a-f]{32,128}$/.test(obj.k)) throw new Error('The key in the setup code looks wrong.');
  return { url: url.toString(), key: obj.k, sheetName: obj.n || '' };
}
